const items = $input.all();

const batchId = $('Create Ingestion Batch').first().json.batch_id;

function cleanString(value) {
    if (value === null || value === undefined) {
        return null;
    }

    const cleaned = String(value).trim();
    return cleaned === "" ? null : cleaned;
}

function parseNumber(value) {
    if (value === null || value === undefined || String(value).trim() === "") {
        return null;
    }

    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : null;
}

function isValidDateTime(value) {
    if (typeof value !== "string") {
        return false;
    }

    const match = value.match(
        /^(\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2}):(\d{2})$/
    );

    if (!match) {
        return false;
    }

    const [, year, month, day, hour, minute, second] = match.map(Number);

    const date = new Date(
        Date.UTC(year, month - 1, day, hour, minute, second)
    );

    return (
        date.getUTCFullYear() === year &&
        date.getUTCMonth() === month - 1 &&
        date.getUTCDate() === day &&
        date.getUTCHours() === hour &&
        date.getUTCMinutes() === minute &&
        date.getUTCSeconds() === second
    );
}

function normalizeAndValidate(raw) {
    const sourceRowNumber = parseNumber(raw.SourceRowNumber);
    const invoiceNo = cleanString(raw.InvoiceNo);
    const stockCode = cleanString(raw.StockCode);
    const description = cleanString(raw.Description);
    const quantity = parseNumber(raw.Quantity);
    const invoiceDate = cleanString(raw.InvoiceDate);
    const unitPrice = parseNumber(raw.UnitPrice);
    const customerId = cleanString(raw.CustomerID);
    const country = cleanString(raw.Country);

    const errors = [];

    if (
        sourceRowNumber === null ||
        !Number.isInteger(sourceRowNumber) ||
        sourceRowNumber <= 0
    ) {
        errors.push("Invalid source row number");
    }

    if (!invoiceNo) errors.push("Missing invoice number");
    if (!stockCode) errors.push("Missing stock code");
    if (!country) errors.push("Missing country");

    if (quantity === null || !Number.isInteger(quantity)) {
        errors.push("Invalid quantity");
    } else if (quantity === 0) {
        errors.push("Quantity cannot be zero");
    }

    if (!isValidDateTime(invoiceDate)) {
        errors.push("Invalid invoice date");
    }

    if (unitPrice === null) {
        errors.push("Invalid unit price");
    } else if (unitPrice < 0) {
        errors.push("Unit price cannot be negative");
    }

    const isCancellation = Boolean(
        invoiceNo?.startsWith("C") || (quantity !== null && quantity < 0)
    );

    return {
        is_valid: errors.length === 0,
        batch_id: batchId,

        source_row_number: sourceRowNumber,

        invoice_no: invoiceNo,
        stock_code: stockCode,
        description,
        quantity,
        invoice_date: invoiceDate,
        unit_price: unitPrice,
        customer_id: customerId,
        country,

        is_cancellation: isCancellation,
        has_missing_description: description === null,
        has_missing_customer_id: customerId === null,
        has_zero_unit_price: unitPrice === 0,

        raw_record: raw,
        rejection_reason: errors.length > 0
            ? errors.join("; ")
            : null,
    };
}

return items.map(item => ({
    json: normalizeAndValidate(item.json),
}));

const records = $input.all()
    .map(item => item.json)
    .filter(r => r.is_valid)
    .map(r => ({
        batch_id: r.batch_id,
        source_row_number: r.source_row_number,
        invoice_no: r.invoice_no,
        stock_code: r.stock_code,
        description: r.description,
        quantity: r.quantity,
        invoice_date: r.invoice_date,
        unit_price: r.unit_price,
        customer_id: r.customer_id,
        country: r.country,
    }));

if (records.length === 0) {
    return [{ json: { rows: [] } }];
}

const BATCH_SIZE = 500;
const batches = [];

for (let i = 0; i < records.length; i += BATCH_SIZE) {
    batches.push(records.slice(i, i + BATCH_SIZE));
}

return batches.map(rows => ({ json: { rows } }));

const records = $input.all()
    .map(item => item.json)
    .filter(r => !r.is_valid)
    .map(r => ({
        batch_id: r.batch_id,
        source_row_number: r.source_row_number,
        raw_record: r.raw_record,
        rejection_reason: r.rejection_reason,
    }));

if (records.length === 0) {
    return [{ json: { rows: [] } }];
}

const BATCH_SIZE = 500;
const batches = [];

for (let i = 0; i < records.length; i += BATCH_SIZE) {
    batches.push(records.slice(i, i + BATCH_SIZE));
}

return batches.map(rows => ({ json: { rows } }));
